def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); boxes=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] in (0,2) or (r,c) in seen: continue
   col=grid[r][c]; seen.add((r,c)); q=[(r,c)]
   for y,x in q:
    for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
      seen.add((a,b)); q.append((a,b))
   t=min(y for y,x in q); d=max(y for y,x in q); l=min(x for y,x in q); rr=max(x for y,x in q)
   boxes.append((t,d,l,rr))
 removed={i for i,(t,d,l,r) in enumerate(boxes) if any(grid[y][x]==2 for y in range(t,d+1) for x in range(l,r+1))}
 change=True
 while change:
  change=False
  for i,(t,d,l,r) in enumerate(boxes):
   if i in removed: continue
   if any(d==boxes[j][0]-1 and max(l,boxes[j][2])<=min(r,boxes[j][3]) for j in removed):
    removed.add(i); change=True
 out=[row[:] for row in grid]
 for i in removed:
  t,d,l,r=boxes[i]
  for y in range(t,d+1):
   for x in range(l,r+1): out[y][x]=0
 return out

